    #{lastSyncTime}, #{lastSyncBy}, #{lastError}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{delFlag}
)

mapper.update:
update crm_product_channel_binding
external_id = #{externalId}, sync_status = #{syncStatus}, last_sync_hash = #{lastSyncHash}, last_sync_time = #{lastSyncTime}, last_sync_by = #{lastSyncBy}, last_error = #{lastError}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag},
